import math

def poisson_pmf(k, mean):
    return math.exp(-mean) * mean**k / math.factorial(k)

def loaves_to_bake(mean, risk):
    k = 0
    p = math.exp(-mean)        # P(X = 0)
    cdf = p
    while 1 - cdf > risk:
        k += 1
        p *= mean / k          # P(X = k) from P(X = k - 1)
        cdf += p
    return k

